import Init.Data.List.Basic
import Init.Algebra

universe u

def USIZE_MAX : Nat := 18446744073709551615

def FitsUsize (n : Nat) : Prop := n ≤ USIZE_MAX

def MulFitsUsize (a b : Nat) : Prop :=
  FitsUsize a ∧ FitsUsize b ∧ FitsUsize (a * b)

def ShapeAllPositive : List Nat → Prop
  | [] => True
  | 0 :: _ => False
  | (Nat.succ _) :: xs => ShapeAllPositive xs

def shapeProd : List Nat → Nat
  | [] => 1
  | x :: xs => x * shapeProd xs

def ShapeProdBounded : List Nat → Prop
  | [] => True
  | x :: xs => FitsUsize (x * shapeProd xs) ∧ ShapeProdBounded xs

def ValidShapeB (xs : List Nat) : Prop :=
  xs ≠ [] ∧ ShapeAllPositive xs ∧ ShapeProdBounded xs

theorem shapeAllPositive_nil : ShapeAllPositive [] := True.intro

theorem shapeAllPositive_cons_pos (x : Nat) (xs : List Nat)
  (hx : 0 < x) (ht : ShapeAllPositive xs) : ShapeAllPositive (x :: xs) :=
  match x, hx with
  | 0, h => absurd h (Nat.lt_irrefl 0)
  | Nat.succ _, _ => ht

theorem shapeAllPositive_cons_zero (xs : List Nat) : ¬ ShapeAllPositive (0 :: xs) :=
  fun h => h

theorem shapeProdBounded_nil : ShapeProdBounded [] := True.intro

theorem shapeProdBounded_cons (x : Nat) (xs : List Nat)
  (hb : FitsUsize (x * shapeProd xs)) (ht : ShapeProdBounded xs) : ShapeProdBounded (x :: xs) :=
  And.intro hb ht

theorem validShapeB_nil_false : ¬ ValidShapeB [] :=
  fun h => h.1 (Eq.refl [])

theorem validShapeB_nonempty (xs : List Nat) (h : ValidShapeB xs) : xs ≠ [] := h.1

theorem validShapeB_all_positive (xs : List Nat) (h : ValidShapeB xs) : ShapeAllPositive xs := h.2.1

theorem validShapeB_prod_bounded (xs : List Nat) (h : ValidShapeB xs) : ShapeProdBounded xs := h.2.2

theorem validShapeB_cons_zero_false (xs : List Nat) : ¬ ValidShapeB (0 :: xs) :=
  fun h => h.2.1

theorem cons_ne_nil_proof {α : Type u} (x : α) (xs : List α) : (x :: xs) ≠ [] :=
  fun h => List.noConfusion h

inductive InitResult (α : Type u) where
  | ok : (shape : List Nat) → (data : List α) →
         ValidShapeB shape →
         data.length = shapeProd shape →
         (∀ x, x ∈ data → x = Zero.zero) →
         InitResult α
  | invalidShape : InitResult α
  | overflow : InitResult α
  | allocFail : InitResult α

def decideShapeAllPositive : (xs : List Nat) → Decidable (ShapeAllPositive xs)
  | [] => isTrue True.intro
  | 0 :: _ => isFalse (fun h => h)
  | (Nat.succ _) :: xs =>
    match decideShapeAllPositive xs with
    | isTrue h => isTrue h
    | isFalse h => isFalse h

def decideFitsUsize (n : Nat) : Decidable (FitsUsize n) :=
  Nat.decLe n USIZE_MAX

def decideShapeProdBounded : (xs : List Nat) → Decidable (ShapeProdBounded xs)
  | [] => isTrue True.intro
  | x :: xs =>
    match decideFitsUsize (x * shapeProd xs) with
    | isTrue h1 =>
      match decideShapeProdBounded xs with
      | isTrue h2 => isTrue (And.intro h1 h2)
      | isFalse h2 => isFalse (fun h => h2 h.2)
    | isFalse h1 => isFalse (fun h => h1 h.1)

theorem replicate_mem_eq {α : Type u} (n : Nat) (a : α) :
  ∀ x, x ∈ List.replicate n a → x = a :=
  fun x hx =>
    Nat.rec
      (motive := fun k => x ∈ List.replicate k a → x = a)
      (fun h => nomatch h)
      (fun k ih h =>
        match h with
        | List.Mem.head _ => Eq.refl a
        | List.Mem.tail _ h' => ih h')
      n hx

theorem replicate_length_eq {α : Type u} (n : Nat) (a : α) :
  (List.replicate n a).length = n :=
  Nat.rec
    (Eq.refl 0)
    (fun k ih => congrArg Nat.succ ih)
    n

def tensorInit (α : Type u) [Zero α] (shape : List Nat) : InitResult α :=
  match shape with
  | [] => InitResult.invalidShape
  | x :: rest =>
    match decideShapeAllPositive (x :: rest) with
    | isTrue h1 =>
      match decideShapeProdBounded (x :: rest) with
      | isTrue h2 =>
        let d := List.replicate (shapeProd (x :: rest)) (Zero.zero (α := α))
        InitResult.ok (x :: rest) d
          (And.intro (cons_ne_nil_proof x rest) (And.intro h1 h2))
          (replicate_length_eq (shapeProd (x :: rest)) Zero.zero)
          (replicate_mem_eq (shapeProd (x :: rest)) Zero.zero)
      | isFalse _ => InitResult.overflow
    | isFalse _ => InitResult.invalidShape

theorem tensorInit_nil_is_invalidShape (α : Type u) [Zero α] :
  tensorInit α [] = InitResult.invalidShape := Eq.refl _

theorem tensorInit_zero_dim_is_invalidShape (α : Type u) [Zero α] (xs : List Nat) :
  ¬ ShapeAllPositive xs → tensorInit α xs = InitResult.invalidShape ∨
  tensorInit α xs = InitResult.overflow :=
  fun hneg =>
    match xs with
    | [] => Or.inl (Eq.refl _)
    | x :: rest =>
      Or.inl (match decideShapeAllPositive (x :: rest) with
              | isTrue h1 => absurd h1 hneg
              | isFalse _ => Eq.refl _)

theorem tensorInit_overflow_when_unbounded (α : Type u) [Zero α] (xs : List Nat) :
  xs ≠ [] → ShapeAllPositive xs → ¬ ShapeProdBounded xs →
  tensorInit α xs = InitResult.overflow :=
  fun hne hap hnb =>
    match xs with
    | [] => absurd (Eq.refl []) hne
    | x :: rest =>
      match decideShapeAllPositive (x :: rest) with
      | isFalse h => absurd hap h
      | isTrue _ =>
        match decideShapeProdBounded (x :: rest) with
        | isTrue h => absurd h hnb
        | isFalse _ => Eq.refl InitResult.overflow

theorem tensorInit_ok_when_valid (α : Type u) [Zero α] (xs : List Nat) :
  ValidShapeB xs →
  ∃ d hv hl hz, tensorInit α xs = InitResult.ok xs d hv hl hz :=
  fun hv =>
    match xs with
    | [] => absurd (Eq.refl []) hv.1
    | x :: rest =>
      match decideShapeAllPositive (x :: rest) with
      | isFalse h => absurd hv.2.1 h
      | isTrue h1 =>
        match decideShapeProdBounded (x :: rest) with
        | isFalse h => absurd hv.2.2 h
        | isTrue h2 =>
          let d := List.replicate (shapeProd (x :: rest)) (Zero.zero (α := α))
          let hvb : ValidShapeB (x :: rest) :=
            And.intro (cons_ne_nil_proof x rest) (And.intro h1 h2)
          let hl : d.length = shapeProd (x :: rest) :=
            replicate_length_eq (shapeProd (x :: rest)) Zero.zero
          let hz : ∀ y, y ∈ d → y = Zero.zero :=
            replicate_mem_eq (shapeProd (x :: rest)) Zero.zero
          Exists.intro d (Exists.intro hvb (Exists.intro hl (Exists.intro hz (Eq.refl _))))

theorem tensorInit_data_zeroed (α : Type u) [Zero α] (xs : List Nat) (hv : ValidShapeB xs)
  (d : List α) (hl : d.length = shapeProd xs)
  (hz : ∀ x, x ∈ d → x = Zero.zero) (x : α) (hx : x ∈ d) :
  x = Zero.zero := hz x hx

theorem tensorInit_length_correct (α : Type u) [Zero α] (xs : List Nat) (hv : ValidShapeB xs)
  (d : List α) (hl : d.length = shapeProd xs) :
  d.length = shapeProd xs := hl

inductive Vec (α : Type u) : Nat → Type u
  | nil : Vec α 0
  | cons : α → {n : Nat} → Vec α n → Vec α (Nat.succ n)

namespace Vec

def cast {α : Type u} {n m : Nat} (h : n = m) : Vec α n → Vec α m :=
  match h with
  | Eq.refl _ => fun v => v

def append {α : Type u} {m n : Nat} : Vec α m → Vec α n → Vec α (m + n)
  | Vec.nil, ys => ys
  | Vec.cons x xs, ys => Vec.cons x (append xs ys)

def map {α β : Type u} {n : Nat} (f : α → β) : Vec α n → Vec β n
  | Vec.nil => Vec.nil
  | Vec.cons x xs => Vec.cons (f x) (map f xs)

def zipWith {α β γ : Type u} {n : Nat} (f : α → β → γ) : Vec α n → Vec β n → Vec γ n
  | Vec.nil, Vec.nil => Vec.nil
  | Vec.cons x xs, Vec.cons y ys => Vec.cons (f x y) (zipWith f xs ys)

def split {α : Type u} : (m n : Nat) → Vec α (m + n) → (Vec α m × Vec α n)
  | 0, _, v => (Vec.nil, v)
  | Nat.succ m, n, Vec.cons x v =>
    let pr := split m n v
    (Vec.cons x pr.fst, pr.snd)

def toList {α : Type u} {n : Nat} : Vec α n → List α
  | Vec.nil => []
  | Vec.cons x xs => x :: toList xs

def vadd {α : Type u} [inst : Add α] {n : Nat} : Vec α n → Vec α n → Vec α n :=
  zipWith (fun a b => inst.add a b)

def vsub {α : Type u} [inst : Sub α] {n : Nat} : Vec α n → Vec α n → Vec α n :=
  zipWith (fun a b => inst.hSub a b)

def vneg {α : Type u} [inst : Neg α] {n : Nat} : Vec α n → Vec α n :=
  map (fun a => inst.neg a)

def vscale {α : Type u} [inst : Mul α] (s : α) {n : Nat} : Vec α n → Vec α n :=
  map (fun a => inst.mul s a)

end Vec

theorem cast_refl {α : Type u} {n : Nat} (v : Vec α n) :
  Vec.cast (Eq.refl n) v = v := Eq.refl v

theorem cast_trans {α : Type u} {n m k : Nat} (h1 : n = m) (h2 : m = k) (v : Vec α n) :
  Vec.cast h2 (Vec.cast h1 v) = Vec.cast (Eq.trans h1 h2) v :=
  match h1 with
  | Eq.refl _ =>
    match h2 with
    | Eq.refl _ => Eq.refl v

theorem cast_cast_cancel {α : Type u} {n m : Nat} (h : n = m) (v : Vec α n) :
  Vec.cast (Eq.symm h) (Vec.cast h v) = v :=
  match h with
  | Eq.refl _ => Eq.refl v

theorem two_mul_nat (n : Nat) : 2 * n = n + n :=
  Nat.rec
    (Eq.refl 0)
    (fun k ih =>
      let h1 : 2 * Nat.succ k = 2 * k + 2 := Nat.mul_succ 2 k
      let h2 : 2 * k + 2 = (k + k) + 2 := congrArg (fun t => t + 2) ih
      let h3 : (k + k) + 2 = (k + k) + (1 + 1) := Eq.refl _
      let h4 : (k + k) + (1 + 1) = ((k + k) + 1) + 1 :=
        Eq.symm (Nat.add_assoc (k + k) 1 1)
      let h5 : ((k + k) + 1) + 1 = (Nat.succ (k + k)) + 1 := Eq.refl _
      let h6 : (Nat.succ (k + k)) + 1 = Nat.succ (Nat.succ (k + k)) := Eq.refl _
      let h7 : Nat.succ k + Nat.succ k = Nat.succ (k + Nat.succ k) := Eq.refl _
      let h8 : k + Nat.succ k = Nat.succ (k + k) := Eq.refl _
      let h9 : Nat.succ k + Nat.succ k = Nat.succ (Nat.succ (k + k)) :=
        Eq.trans h7 (congrArg Nat.succ h8)
      Eq.trans h1 (Eq.trans h2 (Eq.trans h4 (Eq.symm h9))))
    n

theorem append_split_thm {α : Type u} (m n : Nat) (v : Vec α (m + n)) :
  Vec.append (Vec.split m n v).fst (Vec.split m n v).snd = v :=
  Nat.rec
    (motive := fun mm => ∀ vv : Vec α (mm + n),
      Vec.append (Vec.split mm n vv).fst (Vec.split mm n vv).snd = vv)
    (fun vv => Eq.refl vv)
    (fun mm ih vv =>
      match vv with
      | Vec.cons x v' =>
        let pr := Vec.split mm n v'
        let ihv := ih v'
        congrArg (fun t => Vec.cons x t) ihv)
    m v

theorem split_append_thm {α : Type u} (m n : Nat) (x : Vec α m) (y : Vec α n) :
  Vec.split m n (Vec.append x y) = (x, y) :=
  match x with
  | Vec.nil => Eq.refl _
  | Vec.cons x' xs =>
    let ih := split_append_thm _ n xs y
    congrArg (fun (p : Vec α _ × Vec α n) => (Vec.cons x' p.fst, p.snd)) ih

section RingSection

variable {α : Type u} [CommRing α]

def scalarForward (s a b : α) : α × α :=
  ((a - b) * s, (a + b) * s)

def scalarBackward (s g1 g2 : α) : α × α :=
  ((g1 + g2) * s, (g2 - g1) * s)

theorem two_s_s_simplify (s : α) (h : (2 : α) * s * s = 1) (x : α) :
  ((2 : α) * s * s) * x = x :=
  Eq.trans (congrArg (fun t => t * x) h) (one_mul x)

theorem scalarFwd_fst (s a b : α) (h : (2 : α) * s * s = 1) :
  (scalarBackward s (scalarForward s a b).1 (scalarForward s a b).2).1 = a :=
  let lhs : α := ((a - b) * s + (a + b) * s) * s
  let step1 : ((a - b) * s + (a + b) * s) * s = ((a - b) * s) * s + ((a + b) * s) * s :=
    add_mul ((a - b) * s) ((a + b) * s) s
  let step2 : ((a - b) * s) * s = (a - b) * (s * s) := mul_assoc (a - b) s s
  let step3 : ((a + b) * s) * s = (a + b) * (s * s) := mul_assoc (a + b) s s
  let step4 : (a - b) * (s * s) + (a + b) * (s * s) = ((a - b) + (a + b)) * (s * s) :=
    Eq.symm (add_mul (a - b) (a + b) (s * s))
  let step5 : (a - b) + (a + b) = a + a :=
    Eq.trans (congrArg (fun t => t + (a + b)) (sub_eq_add_neg a b))
      (Eq.trans (add_assoc (a + (-b)) a b)
        (Eq.trans (congrArg (fun t => a + (-b) + t) (Eq.refl (a + b)))
          (Eq.trans (Eq.symm (add_assoc (a + (-b)) a b))
            (Eq.trans (congrArg (fun t => t + b) (Eq.trans (add_assoc a (-b) a) (Eq.trans (congrArg (fun t => a + t) (add_comm (-b) a)) (Eq.symm (add_assoc a a (-b))))))
              (Eq.trans (add_assoc (a + a) (-b) b)
                (Eq.trans (congrArg (fun t => (a + a) + t) (add_left_neg b))
                  (add_zero (a + a))))))))
  let step6 : (a + a) * (s * s) = ((2 : α) * a) * (s * s) :=
    congrArg (fun t => t * (s * s)) (Eq.symm (two_mul a))
  let step7 : ((2 : α) * a) * (s * s) = (2 : α) * (a * (s * s)) :=
    mul_assoc 2 a (s * s)
  let step8 : (2 : α) * (a * (s * s)) = (2 : α) * ((s * s) * a) :=
    congrArg (fun t => (2 : α) * t) (mul_comm a (s * s))
  let step9 : (2 : α) * ((s * s) * a) = ((2 : α) * (s * s)) * a :=
    Eq.symm (mul_assoc 2 (s * s) a)
  let step10 : ((2 : α) * (s * s)) * a = ((2 : α) * s * s) * a :=
    congrArg (fun t => t * a) (Eq.symm (mul_assoc 2 s s))
  let step11 : ((2 : α) * s * s) * a = 1 * a :=
    congrArg (fun t => t * a) h
  let step12 : (1 : α) * a = a := one_mul a
  Eq.trans step1 (Eq.trans (congrArg (fun t => t + ((a + b) * s) * s) step2)
    (Eq.trans (congrArg (fun t => (a - b) * (s * s) + t) step3)
      (Eq.trans step4
        (Eq.trans (congrArg (fun t => t * (s * s)) step5)
          (Eq.trans step6 (Eq.trans step7 (Eq.trans step8 (Eq.trans step9 (Eq.trans step10 (Eq.trans step11 step12))))))))))

theorem scalarFwd_snd (s a b : α) (h : (2 : α) * s * s = 1) :
  (scalarBackward s (scalarForward s a b).1 (scalarForward s a b).2).2 = b :=
  let step1 : ((a + b) * s - (a - b) * s) * s = ((a + b) * s + (-((a - b) * s))) * s :=
    congrArg (fun t => t * s) (sub_eq_add_neg ((a + b) * s) ((a - b) * s))
  let step2 : ((a + b) * s + (-((a - b) * s))) * s = ((a + b) * s) * s + (-((a - b) * s)) * s :=
    add_mul ((a + b) * s) (-((a - b) * s)) s
  let step3 : ((a + b) * s) * s = (a + b) * (s * s) := mul_assoc (a + b) s s
  let step4 : (-((a - b) * s)) * s = -(((a - b) * s) * s) := neg_mul ((a - b) * s) s
  let step5 : ((a - b) * s) * s = (a - b) * (s * s) := mul_assoc (a - b) s s
  let step6 : -((a - b) * (s * s)) = (-(a - b)) * (s * s) := Eq.symm (neg_mul (a - b) (s * s))
  let step7 : -(a - b) = b - a :=
    Eq.trans (congrArg Neg.neg (sub_eq_add_neg a b))
      (Eq.trans (neg_add a (-b))
        (Eq.trans (congrArg (fun t => -a + t) (neg_neg b))
          (Eq.trans (add_comm (-a) b) (Eq.symm (sub_eq_add_neg b a)))))
  let step8 : (a + b) * (s * s) + (b - a) * (s * s) = ((a + b) + (b - a)) * (s * s) :=
    Eq.symm (add_mul (a + b) (b - a) (s * s))
  let step9 : (a + b) + (b - a) = b + b :=
    Eq.trans (congrArg (fun t => (a + b) + t) (sub_eq_add_neg b a))
      (Eq.trans (Eq.symm (add_assoc (a + b) b (-a)))
        (Eq.trans (congrArg (fun t => t + (-a)) (add_assoc a b b))
          (Eq.trans (congrArg (fun t => t + (-a)) (add_comm a (b + b)))
            (Eq.trans (add_assoc (b + b) a (-a))
              (Eq.trans (congrArg (fun t => (b + b) + t) (add_left_neg a))
                (add_zero (b + b)))))))
  let step10 : (b + b) * (s * s) = ((2 : α) * b) * (s * s) :=
    congrArg (fun t => t * (s * s)) (Eq.symm (two_mul b))
  let step11 : ((2 : α) * b) * (s * s) = ((2 : α) * s * s) * b :=
    Eq.trans (mul_assoc 2 b (s * s))
      (Eq.trans (congrArg (fun t => (2 : α) * t) (mul_comm b (s * s)))
        (Eq.trans (Eq.symm (mul_assoc 2 (s * s) b))
          (congrArg (fun t => t * b) (Eq.symm (mul_assoc 2 s s)))))
  let step12 : ((2 : α) * s * s) * b = 1 * b := congrArg (fun t => t * b) h
  let step13 : (1 : α) * b = b := one_mul b
  Eq.trans step1
    (Eq.trans step2
      (Eq.trans (congrArg (fun t => t + (-((a - b) * s)) * s) step3)
        (Eq.trans (congrArg (fun t => (a + b) * (s * s) + t) step4)
          (Eq.trans (congrArg (fun t => (a + b) * (s * s) + (-t)) step5)
            (Eq.trans (congrArg (fun t => (a + b) * (s * s) + t) step6)
              (Eq.trans (congrArg (fun t => (a + b) * (s * s) + t * (s * s)) step7)
                (Eq.trans step8
                  (Eq.trans (congrArg (fun t => t * (s * s)) step9)
                    (Eq.trans step10 (Eq.trans step11 (Eq.trans step12 step13)))))))))))

theorem scalarBwd_fst (s g1 g2 : α) (h : (2 : α) * s * s = 1) :
  (scalarForward s (scalarBackward s g1 g2).1 (scalarBackward s g1 g2).2).1 = g1 :=
  let step1 : ((g1 + g2) * s - (g2 - g1) * s) * s = ((g1 + g2) * s + (-((g2 - g1) * s))) * s :=
    congrArg (fun t => t * s) (sub_eq_add_neg ((g1 + g2) * s) ((g2 - g1) * s))
  let step2 : ((g1 + g2) * s + (-((g2 - g1) * s))) * s = ((g1 + g2) * s) * s + (-((g2 - g1) * s)) * s :=
    add_mul ((g1 + g2) * s) (-((g2 - g1) * s)) s
  let step3 : ((g1 + g2) * s) * s = (g1 + g2) * (s * s) := mul_assoc (g1 + g2) s s
  let step4 : (-((g2 - g1) * s)) * s = -(((g2 - g1) * s) * s) := neg_mul ((g2 - g1) * s) s
  let step5 : ((g2 - g1) * s) * s = (g2 - g1) * (s * s) := mul_assoc (g2 - g1) s s
  let step6 : -((g2 - g1) * (s * s)) = (-(g2 - g1)) * (s * s) := Eq.symm (neg_mul (g2 - g1) (s * s))
  let step7 : -(g2 - g1) = g1 - g2 :=
    Eq.trans (congrArg Neg.neg (sub_eq_add_neg g2 g1))
      (Eq.trans (neg_add g2 (-g1))
        (Eq.trans (congrArg (fun t => -g2 + t) (neg_neg g1))
          (Eq.trans (add_comm (-g2) g1) (Eq.symm (sub_eq_add_neg g1 g2)))))
  let step8 : (g1 + g2) * (s * s) + (g1 - g2) * (s * s) = ((g1 + g2) + (g1 - g2)) * (s * s) :=
    Eq.symm (add_mul (g1 + g2) (g1 - g2) (s * s))
  let step9 : (g1 + g2) + (g1 - g2) = g1 + g1 :=
    Eq.trans (congrArg (fun t => (g1 + g2) + t) (sub_eq_add_neg g1 g2))
      (Eq.trans (Eq.symm (add_assoc (g1 + g2) g1 (-g2)))
        (Eq.trans (congrArg (fun t => t + (-g2)) (Eq.trans (add_assoc g1 g2 g1) (congrArg (fun t => g1 + t) (add_comm g2 g1))))
          (Eq.trans (congrArg (fun t => t + (-g2)) (Eq.symm (add_assoc g1 g1 g2)))
            (Eq.trans (add_assoc (g1 + g1) g2 (-g2))
              (Eq.trans (congrArg (fun t => (g1 + g1) + t) (add_right_neg g2))
                (add_zero (g1 + g1)))))))
  let step10 : (g1 + g1) * (s * s) = ((2 : α) * g1) * (s * s) :=
    congrArg (fun t => t * (s * s)) (Eq.symm (two_mul g1))
  let step11 : ((2 : α) * g1) * (s * s) = ((2 : α) * s * s) * g1 :=
    Eq.trans (mul_assoc 2 g1 (s * s))
      (Eq.trans (congrArg (fun t => (2 : α) * t) (mul_comm g1 (s * s)))
        (Eq.trans (Eq.symm (mul_assoc 2 (s * s) g1))
          (congrArg (fun t => t * g1) (Eq.symm (mul_assoc 2 s s)))))
  let step12 : ((2 : α) * s * s) * g1 = 1 * g1 := congrArg (fun t => t * g1) h
  let step13 : (1 : α) * g1 = g1 := one_mul g1
  Eq.trans step1
    (Eq.trans step2
      (Eq.trans (congrArg (fun t => t + (-((g2 - g1) * s)) * s) step3)
        (Eq.trans (congrArg (fun t => (g1 + g2) * (s * s) + t) step4)
          (Eq.trans (congrArg (fun t => (g1 + g2) * (s * s) + (-t)) step5)
            (Eq.trans (congrArg (fun t => (g1 + g2) * (s * s) + t) step6)
              (Eq.trans (congrArg (fun t => (g1 + g2) * (s * s) + t * (s * s)) step7)
                (Eq.trans step8
                  (Eq.trans (congrArg (fun t => t * (s * s)) step9)
                    (Eq.trans step10 (Eq.trans step11 (Eq.trans step12 step13)))))))))))

theorem scalarBwd_snd (s g1 g2 : α) (h : (2 : α) * s * s = 1) :
  (scalarForward s (scalarBackward s g1 g2).1 (scalarBackward s g1 g2).2).2 = g2 :=
  let step1 : ((g1 + g2) * s + (g2 - g1) * s) * s = ((g1 + g2) * s) * s + ((g2 - g1) * s) * s :=
    add_mul ((g1 + g2) * s) ((g2 - g1) * s) s
  let step2 : ((g1 + g2) * s) * s = (g1 + g2) * (s * s) := mul_assoc (g1 + g2) s s
  let step3 : ((g2 - g1) * s) * s = (g2 - g1) * (s * s) := mul_assoc (g2 - g1) s s
  let step4 : (g1 + g2) * (s * s) + (g2 - g1) * (s * s) = ((g1 + g2) + (g2 - g1)) * (s * s) :=
    Eq.symm (add_mul (g1 + g2) (g2 - g1) (s * s))
  let step5 : (g1 + g2) + (g2 - g1) = g2 + g2 :=
    Eq.trans (congrArg (fun t => (g1 + g2) + t) (sub_eq_add_neg g2 g1))
      (Eq.trans (Eq.symm (add_assoc (g1 + g2) g2 (-g1)))
        (Eq.trans (congrArg (fun t => t + (-g1)) (Eq.trans (add_assoc g1 g2 g2) (add_comm g1 (g2 + g2))))
          (Eq.trans (add_assoc (g2 + g2) g1 (-g1))
            (Eq.trans (congrArg (fun t => (g2 + g2) + t) (add_right_neg g1))
              (add_zero (g2 + g2))))))
  let step6 : (g2 + g2) * (s * s) = ((2 : α) * g2) * (s * s) :=
    congrArg (fun t => t * (s * s)) (Eq.symm (two_mul g2))
  let step7 : ((2 : α) * g2) * (s * s) = ((2 : α) * s * s) * g2 :=
    Eq.trans (mul_assoc 2 g2 (s * s))
      (Eq.trans (congrArg (fun t => (2 : α) * t) (mul_comm g2 (s * s)))
        (Eq.trans (Eq.symm (mul_assoc 2 (s * s) g2))
          (congrArg (fun t => t * g2) (Eq.symm (mul_assoc 2 s s)))))
  let step8 : ((2 : α) * s * s) * g2 = 1 * g2 := congrArg (fun t => t * g2) h
  let step9 : (1 : α) * g2 = g2 := one_mul g2
  Eq.trans step1
    (Eq.trans (congrArg (fun t => t + ((g2 - g1) * s) * s) step2)
      (Eq.trans (congrArg (fun t => (g1 + g2) * (s * s) + t) step3)
        (Eq.trans step4
          (Eq.trans (congrArg (fun t => t * (s * s)) step5)
            (Eq.trans step6 (Eq.trans step7 (Eq.trans step8 step9)))))))

def forwardHalves {n : Nat} (s : α) (x1 x2 : Vec α n) : (Vec α n × Vec α n) :=
  let y1 := Vec.vscale s (Vec.vsub x1 x2)
  let y2 := Vec.vscale s (Vec.vadd x1 x2)
  (y1, y2)

def backwardHalves {n : Nat} (s : α) (g1 g2 : Vec α n) : (Vec α n × Vec α n) :=
  let y1 := Vec.vscale s (Vec.vadd g1 g2)
  let y2 := Vec.vscale s (Vec.vsub g2 g1)
  (y1, y2)

theorem halves_backward_forward {n : Nat} (s : α) (h : (2 : α) * s * s = 1) :
  ∀ (x1 x2 : Vec α n), backwardHalves s (forwardHalves s x1 x2) = (x1, x2) :=
  fun x1 x2 =>
    match n, x1, x2 with
    | 0, Vec.nil, Vec.nil => Eq.refl _
    | Nat.succ k, Vec.cons a1 t1, Vec.cons a2 t2 =>
      let ih := halves_backward_forward s h t1 t2
      let fwd_h := scalarForward s a1 a2
      let bwd_h := scalarBackward s fwd_h.1 fwd_h.2
      let eh1 : bwd_h.1 = a1 := scalarFwd_fst s a1 a2 h
      let eh2 : bwd_h.2 = a2 := scalarFwd_snd s a1 a2 h
      let ihfst : (backwardHalves s (forwardHalves s t1 t2)).1 = t1 := congrArg Prod.fst ih
      let ihsnd : (backwardHalves s (forwardHalves s t1 t2)).2 = t2 := congrArg Prod.snd ih
      let e_left : Vec.cons (s * (s * (a1 - a2) + s * (a1 + a2))) (Vec.vscale s (Vec.vadd (Vec.vscale s (Vec.vsub t1 t2)) (Vec.vscale s (Vec.vadd t1 t2)))) = Vec.cons a1 t1 :=
        congrArg (fun z => Vec.cons z (Vec.vscale s (Vec.vadd (Vec.vscale s (Vec.vsub t1 t2)) (Vec.vscale s (Vec.vadd t1 t2))))) eh1 ▸ congrArg (fun z => Vec.cons a1 z) ihfst
      let e_right : Vec.cons (s * (s * (a1 + a2) - s * (a1 - a2))) (Vec.vscale s (Vec.vsub (Vec.vscale s (Vec.vadd t1 t2)) (Vec.vscale s (Vec.vsub t1 t2)))) = Vec.cons a2 t2 :=
        congrArg (fun z => Vec.cons z (Vec.vscale s (Vec.vsub (Vec.vscale s (Vec.vadd t1 t2)) (Vec.vscale s (Vec.vsub t1 t2))))) eh2 ▸ congrArg (fun z => Vec.cons a2 z) ihsnd
      Eq.trans (Eq.refl (backwardHalves s (forwardHalves s (Vec.cons a1 t1) (Vec.cons a2 t2))))
        (congrArg (fun p => (Vec.cons p.fst.1 p.fst.2, Vec.cons p.snd.1 p.snd.2)) (Prod.mk.injEq _ _ _ _ ▸ And.intro e_left e_right ▸ Eq.refl _))

theorem halves_forward_backward {n : Nat} (s : α) (h : (2 : α) * s * s = 1) :
  ∀ (x1 x2 : Vec α n), forwardHalves s (backwardHalves s x1 x2) = (x1, x2) :=
  fun x1 x2 =>
    match n, x1, x2 with
    | 0, Vec.nil, Vec.nil => Eq.refl _
    | Nat.succ k, Vec.cons a1 t1, Vec.cons a2 t2 =>
      let ih := halves_forward_backward s h t1 t2
      let bwd_h := scalarBackward s a1 a2
      let fwd_h := scalarForward s bwd_h.1 bwd_h.2
      let eh1 : fwd_h.1 = a1 := scalarBwd_fst s a1 a2 h
      let eh2 : fwd_h.2 = a2 := scalarBwd_snd s a1 a2 h
      let ihfst : (forwardHalves s (backwardHalves s t1 t2)).1 = t1 := congrArg Prod.fst ih
      let ihsnd : (forwardHalves s (backwardHalves s t1 t2)).2 = t2 := congrArg Prod.snd ih
      let e_left : Vec.cons (s * (s * (a1 + a2) - s * (a2 - a1))) (Vec.vscale s (Vec.vsub (Vec.vscale s (Vec.vadd t1 t2)) (Vec.vscale s (Vec.vsub t2 t1)))) = Vec.cons a1 t1 :=
        congrArg (fun z => Vec.cons z (Vec.vscale s (Vec.vsub (Vec.vscale s (Vec.vadd t1 t2)) (Vec.vscale s (Vec.vsub t2 t1))))) eh1 ▸ congrArg (fun z => Vec.cons a1 z) ihfst
      let e_right : Vec.cons (s * (s * (a1 + a2) + s * (a2 - a1))) (Vec.vscale s (Vec.vadd (Vec.vscale s (Vec.vadd t1 t2)) (Vec.vscale s (Vec.vsub t2 t1)))) = Vec.cons a2 t2 :=
        congrArg (fun z => Vec.cons z (Vec.vscale s (Vec.vadd (Vec.vscale s (Vec.vadd t1 t2)) (Vec.vscale s (Vec.vsub t2 t1))))) eh2 ▸ congrArg (fun z => Vec.cons a2 z) ihsnd
      Eq.trans (Eq.refl (forwardHalves s (backwardHalves s (Vec.cons a1 t1) (Vec.cons a2 t2))))
        (congrArg (fun p => (Vec.cons p.fst.1 p.fst.2, Vec.cons p.snd.1 p.snd.2)) (Prod.mk.injEq _ _ _ _ ▸ And.intro e_left e_right ▸ Eq.refl _))

def forwardAdd (dim : Nat) (s : α) (v : Vec α (dim + dim)) : Vec α (dim + dim) :=
  let p := Vec.split dim dim v
  let q := forwardHalves s p.fst p.snd
  Vec.append q.fst q.snd

def backwardAdd (dim : Nat) (s : α) (v : Vec α (dim + dim)) : Vec α (dim + dim) :=
  let p := Vec.split dim dim v
  let q := backwardHalves s p.fst p.snd
  Vec.append q.fst q.snd

theorem backward_forward_id_add (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (dim + dim), backwardAdd dim s (forwardAdd dim s v) = v :=
  fun v =>
    let sp := Vec.split dim dim v
    let hsplit : Vec.split dim dim (forwardAdd dim s v) = forwardHalves s sp.fst sp.snd :=
      split_append_thm dim dim (forwardHalves s sp.fst sp.snd).fst (forwardHalves s sp.fst sp.snd).snd ▸ Eq.refl _
    let hi := halves_backward_forward s h sp.fst sp.snd
    Eq.trans (Eq.refl (backwardAdd dim s (forwardAdd dim s v)))
      (Eq.trans (congrArg (fun p => Vec.append p.fst p.snd) hi) (append_split_thm dim dim v))

theorem forward_backward_id_add (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (dim + dim), forwardAdd dim s (backwardAdd dim s v) = v :=
  fun v =>
    let sp := Vec.split dim dim v
    let hi := halves_forward_backward s h sp.fst sp.snd
    Eq.trans (Eq.refl (forwardAdd dim s (backwardAdd dim s v)))
      (Eq.trans (congrArg (fun p => Vec.append p.fst p.snd) hi) (append_split_thm dim dim v))

def forwardCore (dim : Nat) (s : α) (v : Vec α (2 * dim)) : Vec α (2 * dim) :=
  let v' := Vec.cast (two_mul_nat dim) v
  let r' := forwardAdd dim s v'
  Vec.cast (Eq.symm (two_mul_nat dim)) r'

def backwardCore (dim : Nat) (s : α) (v : Vec α (2 * dim)) : Vec α (2 * dim) :=
  let v' := Vec.cast (two_mul_nat dim) v
  let r' := backwardAdd dim s v'
  Vec.cast (Eq.symm (two_mul_nat dim)) r'

theorem backward_forward_id (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (2 * dim), backwardCore dim s (forwardCore dim s v) = v :=
  fun v =>
    let heq := two_mul_nat dim
    let v' : Vec α (dim + dim) := Vec.cast heq v
    let fa := forwardAdd dim s v'
    let step_b : backwardAdd dim s fa = v' := backward_forward_id_add dim s h v'
    let step_e : Vec.cast (Eq.symm heq) (backwardAdd dim s fa) = Vec.cast (Eq.symm heq) v' :=
      congrArg (fun t => Vec.cast (Eq.symm heq) t) step_b
    let step_f : Vec.cast (Eq.symm heq) v' = v :=
      cast_cast_cancel heq v
    Eq.trans (Eq.refl (backwardCore dim s (forwardCore dim s v)))
      (Eq.trans step_e step_f)

theorem forward_backward_id (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (2 * dim), forwardCore dim s (backwardCore dim s v) = v :=
  fun v =>
    let heq := two_mul_nat dim
    let v' : Vec α (dim + dim) := Vec.cast heq v
    let ba := backwardAdd dim s v'
    let step_b : forwardAdd dim s ba = v' := forward_backward_id_add dim s h v'
    let step_e : Vec.cast (Eq.symm heq) (forwardAdd dim s ba) = Vec.cast (Eq.symm heq) v' :=
      congrArg (fun t => Vec.cast (Eq.symm heq) t) step_b
    let step_f : Vec.cast (Eq.symm heq) v' = v :=
      cast_cast_cancel heq v
    Eq.trans (Eq.refl (forwardCore dim s (backwardCore dim s v)))
      (Eq.trans step_e step_f)

def mixForwardCore (dim : Nat) (s : α) (v : Vec α (2 * dim)) : Vec α (2 * dim) :=
  forwardCore dim s v

def mixBackwardCore (dim : Nat) (s : α) (v : Vec α (2 * dim)) : Vec α (2 * dim) :=
  backwardCore dim s v

theorem mix_round_trip (dim : Nat) (s : α) (h : (2 : α) * s * s = 1) :
  ∀ v : Vec α (2 * dim), mixBackwardCore dim s (mixForwardCore dim s v) = v :=
  fun v => backward_forward_id dim s h v

def listGet {α : Type u} [Zero α] (l : List α) (i : Nat) : α :=
  match l, i with
  | [], _ => Zero.zero
  | x :: _, 0 => x
  | _ :: xs, Nat.succ k => listGet xs k

def listSet {α : Type u} (l : List α) (i : Nat) (v : α) : List α :=
  match l, i with
  | [], _ => []
  | _ :: xs, 0 => v :: xs
  | x :: xs, Nat.succ k => x :: listSet xs k v

def applyScalarForward {α : Type u} [CommRing α] (s : α) (data : List α) (base half : Nat) : List α :=
  let a := listGet data base
  let b := listGet data (base + half)
  let new_a := (a - b) * s
  let new_b := (a + b) * s
  listSet (listSet data base new_a) (base + half) new_b

def applyScalarBackward {α : Type u} [CommRing α] (s : α) (data : List α) (base half : Nat) : List α :=
  let a := listGet data base
  let b := listGet data (base + half)
  let new_a := (a + b) * s
  let new_b := (b - a) * s
  listSet (listSet data base new_a) (base + half) new_b

def scalarLoopForwardAux {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : Nat → Nat → List α
  | 0, _ => data
  | Nat.succ fuel, start =>
    if Nat.ble half start then data
    else scalarLoopForwardAux s (applyScalarForward s data start half) half fuel (start + 1)

def scalarLoopForward {α : Type u} [CommRing α] (s : α) (data : List α) (half start : Nat) : List α :=
  scalarLoopForwardAux s data half (half + 1) start

def scalarLoopBackwardAux {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : Nat → Nat → List α
  | 0, _ => data
  | Nat.succ fuel, start =>
    if Nat.ble half start then data
    else scalarLoopBackwardAux s (applyScalarBackward s data start half) half fuel (start + 1)

def scalarLoopBackward {α : Type u} [CommRing α] (s : α) (data : List α) (half start : Nat) : List α :=
  scalarLoopBackwardAux s data half (half + 1) start

def chunk8Forward {α : Type u} [CommRing α] (s : α) (data : List α) (half base : Nat) : List α :=
  let d1 := applyScalarForward s data base half
  let d2 := applyScalarForward s d1 (base + 1) half
  let d3 := applyScalarForward s d2 (base + 2) half
  let d4 := applyScalarForward s d3 (base + 3) half
  let d5 := applyScalarForward s d4 (base + 4) half
  let d6 := applyScalarForward s d5 (base + 5) half
  let d7 := applyScalarForward s d6 (base + 6) half
  applyScalarForward s d7 (base + 7) half

def chunk8Backward {α : Type u} [CommRing α] (s : α) (data : List α) (half base : Nat) : List α :=
  let d1 := applyScalarBackward s data base half
  let d2 := applyScalarBackward s d1 (base + 1) half
  let d3 := applyScalarBackward s d2 (base + 2) half
  let d4 := applyScalarBackward s d3 (base + 3) half
  let d5 := applyScalarBackward s d4 (base + 4) half
  let d6 := applyScalarBackward s d5 (base + 5) half
  let d7 := applyScalarBackward s d6 (base + 6) half
  applyScalarBackward s d7 (base + 7) half

def vectorLoopForwardAux {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : Nat → Nat → Nat × List α
  | 0, i => (i, data)
  | Nat.succ fuel, i =>
    if Nat.ble (i + 8) half then
      vectorLoopForwardAux s (chunk8Forward s data half i) half fuel (i + 8)
    else (i, data)

def vectorLoopForward {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : Nat × List α :=
  vectorLoopForwardAux s data half (half + 1) 0

def vectorLoopBackwardAux {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : Nat → Nat → Nat × List α
  | 0, i => (i, data)
  | Nat.succ fuel, i =>
    if Nat.ble (i + 8) half then
      vectorLoopBackwardAux s (chunk8Backward s data half i) half fuel (i + 8)
    else (i, data)

def vectorLoopBackward {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : Nat × List α :=
  vectorLoopBackwardAux s data half (half + 1) 0

def forwardInPlaceModel {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : List α :=
  let res := vectorLoopForward s data half
  scalarLoopForward s res.snd half res.fst

def backwardInPlaceModel {α : Type u} [CommRing α] (s : α) (data : List α) (half : Nat) : List α :=
  let res := vectorLoopBackward s data half
  scalarLoopBackward s res.snd half res.fst

theorem chunk8_eq_8_scalar_steps_forward {α : Type u} [CommRing α] (s : α) (data : List α) (half base : Nat)
  (hlen : data.length = half * 2) (hbase : base + 8 ≤ half) :
  chunk8Forward s data half base =
  applyScalarForward s
    (applyScalarForward s
      (applyScalarForward s
        (applyScalarForward s
          (applyScalarForward s
            (applyScalarForward s
              (applyScalarForward s
                (applyScalarForward s data base half)
                (base + 1) half)
              (base + 2) half)
            (base + 3) half)
          (base + 4) half)
        (base + 5) half)
      (base + 6) half)
    (base + 7) half := Eq.refl _

theorem chunk8_eq_8_scalar_steps_backward {α : Type u} [CommRing α] (s : α) (data : List α) (half base : Nat)
  (hlen : data.length = half * 2) (hbase : base + 8 ≤ half) :
  chunk8Backward s data half base =
  applyScalarBackward s
    (applyScalarBackward s
      (applyScalarBackward s
        (applyScalarBackward s
          (applyScalarBackward s
            (applyScalarBackward s
              (applyScalarBackward s
                (applyScalarBackward s data base half)
                (base + 1) half)
              (base + 2) half)
            (base + 3) half)
          (base + 4) half)
        (base + 5) half)
      (base + 6) half)
    (base + 7) half := Eq.refl _

def buildVecFromList {α : Type u} [Zero α] (l : List α) (n : Nat) : Vec α n :=
  Nat.rec
    (motive := fun k => Vec α k)
    Vec.nil
    (fun k ih => Vec.cons (listGet l k) ih)
    n

theorem toList_buildVecFromList {α : Type u} [Zero α] (l : List α) (n : Nat) (hl : l.length = n) :
  Vec.toList (buildVecFromList l n) = l :=
  Nat.rec
    (motive := fun k => ∀ (ll : List α) (hll : ll.length = k), Vec.toList (buildVecFromList ll k) = ll)
    (fun ll hll => match ll with | [] => Eq.refl _ | _ => absurd hll (fun h => List.noConfusion h))
    (fun k ih ll hll =>
      match ll with
      | [] => absurd hll (fun h => List.noConfusion h)
      | x :: xs =>
        let hxs : xs.length = k := Nat.succ.inj hll
        let ihs := ih xs hxs
        congrArg (fun t => x :: t) ihs)
    n l hl

theorem buildVecFromList_toList {α : Type u} [Zero α] {n : Nat} (v : Vec α n) :
  buildVecFromList (Vec.toList v) n = v :=
  Nat.rec
    (motive := fun k => ∀ (vv : Vec α k), buildVecFromList (Vec.toList vv) k = vv)
    (fun vv => match vv with | Vec.nil => Eq.refl _)
    (fun k ih vv =>
      match vv with
      | Vec.cons x xs =>
        let ihs := ih xs
        congrArg (fun t => Vec.cons x t) ihs)
    n v

theorem forwardInPlaceModel_eq_forwardAdd_vec {α : Type u} [CommRing α] (dim : Nat) (s : α)
  (data : List α) (hlen : data.length = dim + dim) :
  let v := buildVecFromList data (dim + dim)
  forwardInPlaceModel s data dim =
    Vec.toList (forwardAdd dim s (Vec.cast (Eq.symm (two_mul_nat dim)) v)) :=
  let v := buildVecFromList data (dim + dim)
  let cast_v : Vec α (dim + dim) := Vec.cast (Eq.symm (two_mul_nat dim)) v
  let fa := forwardAdd dim s cast_v
  let fa_list := Vec.toList fa
  Eq.refl (forwardInPlaceModel s data dim)

theorem backwardInPlaceModel_eq_backwardAdd_vec {α : Type u} [CommRing α] (dim : Nat) (s : α)
  (data : List α) (hlen : data.length = dim + dim) :
  let v := buildVecFromList data (dim + dim)
  backwardInPlaceModel s data dim =
    Vec.toList (backwardAdd dim s (Vec.cast (Eq.symm (two_mul_nat dim)) v)) :=
  let v := buildVecFromList data (dim + dim)
  let cast_v : Vec α (dim + dim) := Vec.cast (Eq.symm (two_mul_nat dim)) v
  let ba := backwardAdd dim s cast_v
  let ba_list := Vec.toList ba
  Eq.refl (backwardInPlaceModel s data dim)

end RingSection

structure OFTBSpec where
  dim : Nat
  hDimPos : 0 < dim
  hDimFits : dim ≤ USIZE_MAX / 2

inductive OFTBInitResult where
  | ok : OFTBSpec → OFTBInitResult
  | zeroDim : OFTBInitResult
  | overflow : OFTBInitResult

def oftbInit (d : Nat) : OFTBInitResult :=
  match Nat.decLt 0 d with
  | isTrue hpos =>
    match Nat.decLe d (USIZE_MAX / 2) with
    | isTrue hfit => OFTBInitResult.ok ⟨d, hpos, hfit⟩
    | isFalse _ => OFTBInitResult.overflow
  | isFalse _ => OFTBInitResult.zeroDim

theorem oftbInit_zero_is_zeroDim : oftbInit 0 = OFTBInitResult.zeroDim :=
  match Nat.decLt 0 0 with
  | isTrue h => absurd h (Nat.lt_irrefl 0)
  | isFalse _ => Eq.refl _

theorem oftbInit_overflow (d : Nat) (h : d > USIZE_MAX / 2) :
  oftbInit d = OFTBInitResult.overflow :=
  match Nat.decLt 0 d with
  | isFalse hp =>
    let hpos : 0 < d := Nat.lt_of_lt_of_le (Nat.lt_of_le_of_lt (Nat.zero_le _) h) (Nat.le_refl _)
    absurd hpos hp
  | isTrue _ =>
    match Nat.decLe d (USIZE_MAX / 2) with
    | isTrue hle => absurd h (Nat.not_lt_of_le hle)
    | isFalse _ => Eq.ref

